'use strict';
// Design v0.2 section 3: generate JSPARK-FORGE.md (the plain instruction file for tools without plugins).
// Usage: node scripts/build-plain.js   (writes JSPARK-FORGE.md at the repository top)
const fs = require('fs');
const path = require('path');

const read = (root, ...p) => fs.readFileSync(path.join(root, ...p), 'utf8').replace(/\r\n/g, '\n').trim();

function build(root) {
  const out = [];
  out.push('# JSPARK Forge: plain instructions',
    '',
    'For tools that cannot install the JSPARK Forge plugin. Generated by `scripts/build-plain.js` from the same files',
    'the plugin uses; do not edit it by hand.',
    '',
    '## Grounding rule',
    '',
    read(root, 'rules', 'grounding.md'),
    '',
    '## Short-by-default rule',
    '',
    read(root, 'rules', 'short-answers.md'),
    '',
    "## Someone else's repository",
    '',
    'When the repository is not yours (you are reviewing it):',
    '',
    require('./lib/setup').GUEST_DATA_LINE,
    '',
    '## Commands to stop and ask about',
    '',
    'Before you run any of these, stop and ask the user to confirm in words. Never run them on your own.',
    '');
  const list = JSON.parse(read(root, 'rules', 'default-blocklist.json'));
  for (const [id, e] of Object.entries(list)) {
    out.push(`- ${id}: ${e.plain}${e.hardPlain ? `. Worse: ${e.hardPlain}` : ''}`);
  }
  out.push('', '## Skill template', '',
    'One reusable task. Copy it to `skills/<name>/SKILL.md` and never overwrite an existing file.', '',
    '````markdown', read(root, 'templates', 'skill.md'), '````', '',
    '## Brief template', '',
    'One job for one helper. Copy it to `.jspark-forge/briefs/<name>.md` and never overwrite an existing file.', '',
    '````markdown', read(root, 'templates', 'brief.md'), '````', '');
  const tiersFile = path.join(root, 'rules', 'model-tiers.json');
  if (fs.existsSync(tiersFile)) {
    const j = JSON.parse(read(root, 'rules', 'model-tiers.json'));
    const tiers = j.tiers && typeof j.tiers === 'object' ? j.tiers : j;
    // A tier is "model" or { model, why }.
    const rows = Object.entries(tiers).map(([k, v]) => [k, typeof v === 'string' ? { model: v } : v]).filter(([, v]) => v && v.model);
    out.push('## Model map', '',
      'Pick the model by the kind of job. Planning and review: strongest. Building from a reviewed plan: standard.',
      'Mechanical checks: light.', '');
    for (const [k, v] of rows) out.push(`- ${k}: ${v.model}${v.why ? `. Why: ${v.why}` : ''}`);
    out.push('');
  }
  return out.join('\n').replace(/\n+$/, '\n');
}

module.exports = { build };

if (require.main === module) {
  const root = path.join(__dirname, '..');
  fs.writeFileSync(path.join(root, 'JSPARK-FORGE.md'), build(root));
  process.stdout.write('Wrote JSPARK-FORGE.md\n');
}
